SELECT id, type, target_id, result, reason, ai_result, reviewer_id, review_time
FROM audit_record


        AND type = #{type}


        AND result = #{result}


        AND reviewer_id = #{reviewerId}


ORDER BY review_time DESC, id DESC

SELECT id, type, target_id, result, reason, ai_result, reviewer_id, review_time
FROM audit_record
WHERE type = #{type}
  AND target_id = #{targetId}
ORDER BY review_time DESC, id DESC
